# Fable品質スキル インストーラー (Windows用 / PowerShell 5.1・7 両対応)
# 使い方:
#   インストール:     powershell -ExecutionPolicy Bypass -File "$HOME\Downloads\fable-skills-installer.ps1"
#   アンインストール: 上記の末尾に -Uninstall を付ける
# 何度実行しても安全（冪等）。
param([switch]$Uninstall)
$ErrorActionPreference = "Stop"
$claudeDir = Join-Path $HOME ".claude"
$globalMd  = Join-Path $claudeDir "CLAUDE.md"
$utf8      = New-Object System.Text.UTF8Encoding($false)
$skills    = @("fable-core", "fable-check", "fable-refactor")

function Remove-Snippet {
    if (Test-Path $globalMd) {
        $text = [System.IO.File]::ReadAllText($globalMd)
        $pattern = '(?s)\r?\n?<!-- fable-quality:begin -->.*?<!-- fable-quality:end -->[ \t]*\r?\n?'
        $new = [System.Text.RegularExpressions.Regex]::Replace($text, $pattern, "")
        [System.IO.File]::WriteAllText($globalMd, $new, $utf8)
    }
}

if ($Uninstall) {
    foreach ($s in $skills) {
        $p = Join-Path $claudeDir (Join-Path "skills" $s)
        if (Test-Path $p) {
            Remove-Item -Recurse -Force $p
            Write-Host ("removed: ~/.claude/skills/" + $s)
        }
    }
    Remove-Snippet
    Write-Host "アンインストール完了。Fable品質モードの追加分のみ削除しました（他の設定は無変更）。"
    exit 0
}

$files = @{}
$files['skills/fable-core/SKILL.md'] = ''
$files['skills/fable-core/references/fable-vs-opus.md'] = ''
$files['skills/fable-check/SKILL.md'] = ''
$files['skills/fable-refactor/SKILL.md'] = ''

foreach ($rel in $files.Keys) {
    $parts = $rel -split '/'
    $dest = $claudeDir
    foreach ($p in $parts) { $dest = Join-Path $dest $p }
    $dir = Split-Path $dest -Parent
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
    $content = $utf8.GetString([System.Convert]::FromBase64String($files[$rel]))
    [System.IO.File]::WriteAllText($dest, $content, $utf8)
    Write-Host ("installed: ~/.claude/" + $rel)
}

$snippet = $utf8.GetString([System.Convert]::FromBase64String(''))
New-Item -ItemType Directory -Force -Path $claudeDir | Out-Null
Remove-Snippet
$existing = ""
if (Test-Path $globalMd) { $existing = [System.IO.File]::ReadAllText($globalMd) }
$sep = ""
if ($existing.TrimEnd().Length -gt 0) { $sep = "`r`n`r`n" }
[System.IO.File]::WriteAllText($globalMd, ($existing.TrimEnd() + $sep + $snippet + "`r`n"), $utf8)
Write-Host "updated: ~/.claude/CLAUDE.md"
Write-Host ""
Write-Host "完了。次回以降、このPCのどのフォルダで Claude Code を開いても Fable品質モードが有効です。"
